use crate::PatternRenderer;
use orbital_core::client::helpers::*;
use orbital_core::Value;
use ratatui::layout::Rect;
use ratatui::Frame;

/// Renderer for the `state-machine-view` pattern.
pub struct StateMachineViewRenderer;

impl StateMachineViewRenderer {
    const NAME: &str = "state-machine-view";
}

impl PatternRenderer for StateMachineViewRenderer {
    fn pattern_name(&self) -> &str {
        Self::NAME
    }

    fn render(
        &self,
        frame: &mut Frame,
        area: Rect,
        props: &Value,
        _entity: Option<&Value>,
        _ctx: &mut RenderContext<'_>,
    ) {
        use ratatui::style::{Color, Style};
        use ratatui::text::{Line, Text};
        use ratatui::widgets::{Block, Borders, Paragraph};
        let is_loading = get_bool_or(props, "isLoading", false);
        let error = get_string_or(props, "error", "");
        if is_loading {
            frame.render_widget(Paragraph::new(Line::from("⟳ Loading…")), area);
            return;
        }
        if !error.is_empty() {
            frame.render_widget(
                Paragraph::new(Line::from(format!("⚠ {}", error)).style(Style::default().fg(Color::Red))),
                area,
            );
            return;
        }
        let title = get_string_or(props, "title", "State Machine");
        let layout = props.as_object().and_then(|o| o.get("layoutData"));
        let mut lines = vec![Line::from(title).style(Style::default().fg(Color::Cyan))];
        if let Some(ld) = layout {
            let nodes = get_array(ld, "nodes");
            let edges = get_array(ld, "edges");
            lines.push(Line::from(format!("  {} states, {} transitions", nodes.len(), edges.len())));
            for node in nodes.iter().take(6) {
                let label = get_string_or(node, "label", &get_string_or(node, "id", "?"));
                let active = get_bool_or(node, "active", false);
                let mark = if active { "●" } else { "○" };
                lines.push(Line::from(format!("  {} {}", mark, label))
                    .style(if active { Style::default().fg(Color::Green) } else { Style::default() }));
            }
        }
        frame.render_widget(
            Paragraph::new(Text::from(lines)).block(Block::default().borders(Borders::ALL).title("state-machine-view")),
            area,
        );
    }
}
